package io.bmsride.monitor;
import android.app.*;import android.content.*;import android.os.*;import android.location.*;import org.json.*;import java.util.*;
@SuppressWarnings("MissingPermission") public class MonitorService extends Service implements Ble.Listener,LocationListener {
 final Handler h=new Handler(Looper.getMainLooper()); final Local binder=new Local(); Ble ble; Protocol.Battery battery; String status="未连接"; long seq=0,gpsAt=0; double speed=Double.NaN,km=0,acc=Double.NaN; Location last; LocationManager loc; final TripEnergy energy=new TripEnergy(); double lastPower=Double.NaN; boolean gps=false; double capacityOverride=Double.NaN; final TripHistory history=new TripHistory(); 
 public class Local extends Binder{MonitorService service(){return MonitorService.this;}}
 public IBinder onBind(Intent i){return binder;}
 public void onCreate(){super.onCreate();capacityOverride=getSharedPreferences("bms",MODE_PRIVATE).getFloat("capacity",Float.NaN);ble=new Ble(this,this);loc=getSystemService(LocationManager.class);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("monitor","BMS 监测",NotificationManager.IMPORTANCE_LOW));h.post(loop);h.post(poll);}
 public int onStartCommand(Intent i,int flags,int id){Notification n=new Notification.Builder(this,"monitor").setSmallIcon(android.R.drawable.ic_menu_compass).setContentTitle("BMS随行20").setContentText("正在监测 · 点击打开").setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build();startForeground(1,n);return START_NOT_STICKY;}
 public void status(String s){status=s;}public void data(Protocol.Battery b){battery=b;if(b==null)lastPower=Double.NaN;}
 void enableGps(){if(gps)return;try{loc.requestLocationUpdates(LocationManager.GPS_PROVIDER,1000,0,this);gps=true;}catch(Exception e){status="GPS 不可用: "+e.getMessage();}}
 void disableGps(){loc.removeUpdates(this);gps=false;last=null;speed=Double.NaN;gpsAt=0;lastPower=Double.NaN;}
 double dischargePower(long now){Protocol.Battery b=battery;return b!=null&&now>=b.time&&now-b.time<=5000&&Double.isFinite(b.voltage)&&Double.isFinite(b.current)?Math.max(0,-b.voltage*b.current):Double.NaN;}
 public void onLocationChanged(Location l){if(!gps)return;long now=System.currentTimeMillis();if(!l.hasAccuracy()||l.getAccuracy()>35||Math.abs(now-l.getTime())>5000){last=null;lastPower=Double.NaN;return;}speed=l.hasSpeed()?l.getSpeed()*3.6:Double.NaN;acc=l.getAccuracy();gpsAt=now;history.observeSpeed(speed);double power=dischargePower(now);if(last!=null){double dist=last.distanceTo(l);double seconds=(l.getElapsedRealtimeNanos()-last.getElapsedRealtimeNanos())/1e9;if(seconds>0&&seconds<5&&l.hasSpeed()&&dist/seconds<60){double stepKm=l.getSpeed()>0.8?dist/1000:0;km+=stepKm;energy.add(seconds,stepKm,lastPower,power);}}last=l;lastPower=power;}
 public void onProviderEnabled(String p){}public void onProviderDisabled(String p){speed=Double.NaN;gpsAt=0;last=null;lastPower=Double.NaN;}public void onStatusChanged(String p,int s,Bundle b){}
 void disconnectBattery(){ble.close();battery=null;lastPower=Double.NaN;status="未连接";}
 void resetTrip(){history.clear();km=0;energy.clear();last=null;lastPower=Double.NaN;}
 void setCapacity(double ah){capacityOverride=ah;getSharedPreferences("bms",MODE_PRIVATE).edit().putFloat("capacity",(float)ah).apply();}
 static Object num(double x){return Double.isFinite(x)?x:JSONObject.NULL;}
 JSONObject snapshot(){long now=System.currentTimeMillis();Protocol.Battery b=battery;boolean valid=b!=null&&now>=b.time&&now-b.time<=5000;boolean g=gps&&gpsAt>0&&now>=gpsAt&&now-gpsAt<=5000;double eff=valid&&g?energy.efficiency():Double.NaN;double ah=valid?(Double.isFinite(b.ah)?b.ah:capacityOverride*b.soc/100):Double.NaN;try{JSONObject j=new JSONObject();j.put("v",1).put("seq",seq).put("bmsValid",valid).put("gpsValid",g).put("soc",valid?num(b.soc):JSONObject.NULL).put("voltage",valid?num(b.voltage):JSONObject.NULL).put("current",valid?num(b.current):JSONObject.NULL).put("power",valid?num(b.voltage*b.current):JSONObject.NULL).put("ah",num(ah)).put("temp",valid?num(b.temp):JSONObject.NULL).put("mos",valid?num(b.mos):JSONObject.NULL).put("delta",valid?num(b.delta()):JSONObject.NULL).put("speed",g?num(speed):JSONObject.NULL).put("km",num(km)).put("eff",num(eff)).put("range",valid?num(b.voltage*ah/eff):JSONObject.NULL).put("accuracy",g?num(acc):JSONObject.NULL);JSONArray a=new JSONArray();if(valid)for(double c:b.cells)a.put(c);j.put("cells",a).put("maxSpeed",num(history.maxSpeed()));JSONArray ts=new JSONArray();if(valid)for(double t:b.temps)ts.put(num(t));j.put("temps",ts).put("mosFlags",valid&&b.mosFlags>=0?b.mosFlags:JSONObject.NULL).put("alarm",valid&&b.alarm!=null?b.alarm:JSONObject.NULL).put("protection",valid&&b.protection!=null?b.protection:JSONObject.NULL).put("fault",valid&&b.fault!=null?b.fault:JSONObject.NULL);return j;}catch(Exception ex){return new JSONObject();}}
 final Runnable poll=new Runnable(){public void run(){ble.tick();h.postDelayed(this,500);}};
 final Runnable loop=new Runnable(){public void run(){seq++;JSONObject sample=snapshot();history.add(SystemClock.elapsedRealtime(),sample.optDouble("speed",Double.NaN),sample.optDouble("eff",Double.NaN));h.postDelayed(this,1000);}};
 public void onDestroy(){h.removeCallbacksAndMessages(null);ble.close();disableGps();super.onDestroy();}
}
